namespace {using namespace gf;unsigned checks=0;void check(bool x,const char* why){++checks;if(!x){std::fprintf(stderr,"guide popup: %s\n",why);std::abort();}}
ByteView view(const std::vector<u8>& b){return {b.data(),b.size()};}std::vector<u8> read(const std::string& p){std::ifstream f(p,std::ios::binary);return {std::istreambuf_iterator<char>(f),{}};}
void owned(){auto fixture=hsd_shape_fixture::fixture();auto bytes=fixture.archive();HsdRecordAnimationBank bank;HsdShapeRecord shape;std::string error;check(bank.load(view(bytes),&error)&&shape.load(bank,0,&error),"owned single shape");for(unsigned n=0;n<=16;++n){std::vector<HsdVertex> v;f32 value=-1;const f32 at=n*.25f;check(shape.sample_fractional(at,&v,&value,&error)&&value==at*.25f&&v[0].position[0]==-1-at*.25f,"explicit fractional entry not integer truncation");}
    RecordingRenderBackend backend;RenderEngine render(backend);check(render.initialize({640,480,false,true,"owned guide shape"},nullptr,&error),"recording backend");ShapeModelScene scene;check(scene.load(bank,0,render,900,&error),"shared shape scene");Camera camera;camera.eye[2]=10;camera.target[2]=0;camera.near_plane=.1f;camera.far_plane=100;
    auto draw=[&](bool replacement,f32 alpha){render.begin_frame({});render.reset_arena();check(replacement?scene.sample_fractional_alpha(2,Mat4{},alpha,&error):scene.sample(2,Mat4{},&error),"sample draw");check(scene.draw(render,camera)>0&&render.end_frame(),"owned nonempty shape");render.present();return backend.last_frame_digest();};const auto before=draw(false,0);check(draw(true,.5f)!=before&&draw(false,0)==before,"explicit replacement alpha and old default restoration");
    for(f32 bad:{-1.f,1.1f,NAN,INFINITY}){check(!scene.sample_fractional_alpha(2,Mat4{},bad,&error),"bad alpha refusal");render.begin_frame({});render.reset_arena();check(scene.draw(render,camera)==0&&render.end_frame(),"no prior shape replay after failed sample");render.present();}
    check(!scene.sample_fractional_alpha(-1,Mat4{},1,&error)&&!scene.sample_fractional_alpha(5,Mat4{},1,&error),"fractional time guards");render.shutdown();
    StoryGuidePopupArt art;for(unsigned n=0;n<152;++n)check(!art.load({nullptr,n}),"profile missing input refuses");std::printf("Story popup owned: %u checks PASS\n",checks);
}
void frame(FILE* f,const StoryGuidePopupFrame& s,unsigned scenario,unsigned tick,u32 draws,u64 digest){for(u32 x:{scenario,tick,u32(s.source_message),u32(s.record),u32(s.phase),u32(u16(s.counter)),u32(u16(s.duration)),s.callbacks,s.character_tick,s.total,s.maximum_line,u32(s.characters),u32(s.visible),u32(s.drawn_complete),f32_to_bits(s.shape_frame),f32_to_bits(s.alpha),s.text_x,s.text_y,draws,u32(digest>>32),u32(digest)}){u8 b[4];store_be32(b,x);check(std::fwrite(b,1,4,f)==4,"timeline wire");}}
void source(const std::string& home,const std::string& base){const auto dir=home+"/editor-guide-recovery-v1/";auto a=read(home+"/guide-popup-art-v1/popup.gfgp"),b=read(dir+"fmg00_mdl.arc"),fp=read(dir+"guide-font.gffn"),atlas=read(dir+"guide-font.tpl"),txt=read(dir+"guide-text.gftx");SourceFont font;SourceMessageBank messages;StoryGuidePopupArt art;std::string error;check(font.load(view(fp),view(atlas),&error)&&messages.load(view(txt),font,&error)&&art.load(view(a)),"source inputs");
    FILE* out=std::fopen((base+".timeline").c_str(),"wx");check(out,"exclusive timeline");unsigned frames=0;
    for(unsigned scenario=0;scenario<4;++scenario){RecordingRenderBackend backend;RenderEngine render(backend);check(render.initialize({640,480,false,true,"Story popup CPU"},nullptr,&error),"source renderer");StoryGuidePopup popup;const bool loaded=popup.load(view(b),art,font,messages,render,&error);if(!loaded)std::fprintf(stderr,"load: %s\n",error.c_str());check(loaded&&popup.begin(scenario%2?14:13,&error),"source prepared message component");check(!popup.begin(13,&error),"no live reentry");unsigned waiting=0;
        for(unsigned tick=0;tick<400;++tick){const auto prior=popup.frame();bool press=false;if(scenario>=2&&tick==11)press=true;if(prior.phase==4&&++waiting==3)press=true;render.begin_frame({});render.reset_arena();const bool stepped=popup.step(press,&error),drawn=stepped&&popup.draw(render,&error);if(!drawn)std::fprintf(stderr,"scenario%u tick%u: %s\n",scenario,tick,error.c_str());check(drawn&&render.end_frame(),"native update and source panel/glyph submission");render.present();check(!popup.draw(render,&error),"duplicate draw rejected");const auto& s=popup.frame();check(s.maximum_line==(scenario%2?31u:36u)&&s.total==(scenario%2?56u:36u)&&s.record==1&&s.text_x==(scenario%2?197u:172u)&&s.text_y==(scenario%2?308u:320u),"measured tokens not header width/count");check((backend.draws()>0)==s.visible,"visible frame nonempty or final hidden");frame(out,s,scenario,tick,backend.draws(),backend.last_frame_digest());++frames;if(!popup.active()){check(!popup.step(false,&error),"closed component not VM completion");break;}check(tick<399,"bounded message lifecycle");}
        render.shutdown();
    }
    check(std::fclose(out)==0,"timeline close");HsdRecordAnimationBank bank;check(bank.load(view(b),&error),"shape corpus bank");FILE* geometry=std::fopen((base+".geometry").c_str(),"wx");check(geometry,"geometry output");for(unsigned record=0;record<2;++record){HsdShapeRecord shape;check(shape.load(bank,u16(record),&error,true),"source shape corpus");for(unsigned t=0;t<=80;++t){std::vector<HsdVertex> vertices;f32 value=0;check(shape.sample_fractional(t*.25f,&vertices,&value,&error),"quarter-time corpus");for(const auto& v:vertices)std::fprintf(geometry,"%u %u %u %.9g %.9g %.9g %.9g\n",record,t,v.source_position_index,value,v.position[0],v.position[1],v.position[2]);}}check(std::fclose(geometry)==0,"geometry close");std::printf("Story prepared guide popup: %u callbacks, source panel/text only; indicators/VM/voice/readiness unjoined\n",frames);
}
}
int main(int argc,char** argv){owned();if(argc==3)source(argv[1],argv[2]);else if(argc!=1)return 2;return 0;}
